import { Table, StringColumn, GenericColumn, ReferenceColumn, BooleanColumn, GuidColumn, IntegerColumn } from '../../db'

export const sp_container = Table({
    allowWebServiceAccess: true,
    display: 'name',
    extends: 'sys_metadata',
    label: 'Container',
    name: 'sp_container',
    schema: {
        semantic_tag: StringColumn({
            choices: {
                main: {
                    label: 'Main',
                    sequence: 1,
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Semantic tag',
        }),
        background_style: StringColumn({
            choices: {
                contain: {
                    label: 'Contain',
                    sequence: 3,
                },
                repeat: {
                    label: 'Repeating',
                    sequence: 4,
                },
                default: {
                    label: 'Default',
                    sequence: 1,
                },
                cover: {
                    label: 'Cover',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Background style',
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 255,
        }),
        sys_id: GuidColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        container_class_name: StringColumn({
            label: 'CSS class',
        }),
        sp_page: ReferenceColumn({
            cascadeRule: 'delete',
            label: 'Page',
            referenceTable: 'sp_page',
        }),
        title: StringColumn({
            label: [
                {
                    hint: 'Provide a heading to screen readers that describes the contents of this container.',
                    label: 'Screen reader title',
                    plural: 'Screen reader titles',
                    language: 'en',
                },
            ],
            maxLength: 100,
        }),
        background_image: GenericColumn({
            columnType: 'user_image',
            label: 'Background image',
        }),
        background_color: GenericColumn({
            columnType: 'color',
            label: [
                {
                    hint: 'Background color HEX value (e.g. #000000)',
                    label: 'Background color',
                    plural: 'Background colors',
                    language: 'en',
                },
            ],
        }),
        class_name: StringColumn({
            label: 'Parent class',
        }),
        subheader: BooleanColumn({
            label: 'Move to header',
        }),
        bootstrap_alt: BooleanColumn({
            label: 'Bootstrap alternative',
        }),
        width: StringColumn({
            choices: {
                container: {
                    label: 'Fixed',
                    sequence: 1,
                },
                'container-fluid': {
                    label: 'Fluid',
                    sequence: 2,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Width',
        }),
        order: IntegerColumn({
            label: 'Order',
        }),
    },
})
